SELECT count(*) AS matched, sum(CASE WHEN p.amount <> d.amount OR (p.amount IS NULL) <> (d.amount IS NULL) THEN 1 ELSE 0 END) AS differing, sum(CASE WHEN d.amount IS NULL THEN 1 ELSE 0 END) AS dev_nulls FROM prod.orders p JOIN db.orders d ON p.id = d.id;
SELECT count(*) AS dup_dev_ids FROM (SELECT id FROM db.orders GROUP BY id HAVING count(*)>1) x;
SELECT count(*) AS prod_ids_not_in_dev FROM prod.orders p WHERE NOT EXISTS (SELECT 1 FROM db.orders d WHERE d.id=p.id);

